1	import { ConfigValidationError } from "@continuedev/config-yaml";
2	import { IDE, RuleWithSource } from "../..";
3	import { getAllDotContinueDefinitionFiles } from "../loadLocalAssistants";
4	import { convertMarkdownRuleToContinueRule } from "./parseMarkdownRule";
5	
6	/**
7	 * Loads rules from markdown files in the .continue/rules directory
8	 */
9	export async function loadMarkdownRules(ide: IDE): Promise<{
10	  rules: RuleWithSource[];
11	  errors: ConfigValidationError[];
12	}> {
13	  const errors: ConfigValidationError[] = [];
14	  const rules: RuleWithSource[] = [];
15	
16	  try {
17	    // Get all .md files from .continue/rules
18	    const markdownFiles = await getAllDotContinueDefinitionFiles(
19	      ide,
20	      { includeGlobal: true, includeWorkspace: true },
21	      "rules",
22	    );
23	
24	    // Filter to just .md files
25	    const mdFiles = markdownFiles.filter((file) => file.path.endsWith(".md"));
26	
27	    // Process each markdown file
28	    for (const file of mdFiles) {
29	      try {
30	        const rule = convertMarkdownRuleToContinueRule(file.path, file.content);
31	        rules.push(rule);
32	      } catch (e) {
33	        errors.push({
34	          fatal: false,
35	          message: `Failed to parse markdown rule file ${file.path}: ${e instanceof Error ? e.message : e}`,
36	        });
37	      }
38	    }
39	  } catch (e) {
40	    errors.push({
41	      fatal: false,
42	      message: `Error loading markdown rule files: ${e instanceof Error ? e.message : e}`,
43	    });
44	  }
45	
46	  return { rules, errors };
47	}
