import { RuleFrontmatter } from "./parseMarkdownRule";

/**
 * The file extension used for markdown rule files.
 */
export const RULE_FILE_EXTENSION = "md";

export interface CreateRuleMarkdownOptions {
  description?: string;
  globs?: string | string[];
  alwaysApply?: boolean;
}

/**
 * Sanitizes a rule name for use in a filename.
 *
 * - Converts to lowercase
 * - Removes any characters that aren't alphanumeric, spaces, or hyphens
 * - Replaces runs of whitespace with a single hyphen
 * - Trims leading/trailing hyphens
 *
 * Returns an empty string for empty or whitespace-only input.
 */
export function sanitizeRuleName(name: string): string {
  return name
    .toLowerCase()
    .replace(/[^a-z0-9\s-]/g, "")
    .replace(/\s+/g, "-")
    .replace(/^-+|-+$/g, "");
}

/**
 * Constructs the file path for a rule within a workspace's
 * `.continue/rules` directory.
 */
export function createRuleFilePath(
  workspaceDir: string,
  ruleName: string,
): string {
  const sanitizedName = sanitizeRuleName(ruleName);
  return `${workspaceDir}/.continue/rules/${sanitizedName}.${RULE_FILE_EXTENSION}`;
}

/**
 * Combines YAML frontmatter and markdown content into a single string.
 *
 * The output is guaranteed to be parseable by `parseMarkdownRule`.
 */
export function createMarkdownWithFrontmatter(
  frontmatter: RuleFrontmatter,
  markdown: string,
): string {
  const frontmatterYaml = YAML.stringify(frontmatter).trim();
  return `---\n${frontmatterYaml}\n---\n\n${markdown}`;
}

/**
 * Generates markdown for a rule with optional YAML frontmatter.
 *
 * Frontmatter fields are only included when provided. `alwaysApply` is
 * only included when it is explicitly set to `false`.
 */
export function createRuleMarkdown(
  name: string,
  ruleContent: string,
  options: CreateRuleMarkdownOptions = {},
): string {
  const frontmatter: RuleFrontmatter = {};

  if (options.globs) {
    frontmatter.globs =
      typeof options.globs === "string" ? options.globs.trim() : options.globs;
  }

  if (options.description) {
    frontmatter.description = options.description.trim();
  }

  if (options.alwaysApply === false) {
    frontmatter.alwaysApply = options.alwaysApply;
  }

  const markdown = `# ${name}\n\n${ruleContent}`;

  return createMarkdownWithFrontmatter(frontmatter, markdown);
}
