 * Returns the initial file content for a new block of the given type.
 *
 * Rules are created as markdown (with YAML frontmatter); all other block
 * types are serialized as YAML.
 */
export function getFileContent(blockType: BlockType): string {
  if (blockType === "rules") {
    return createRuleMarkdown("New Rule", "Your rule content", {
      description: "A description of your rule",
    });
  }

  return YAML.stringify(getContentsForNewBlock(blockType));
}

/**
 * Finds the first available file URI within `baseDirUri` for the given block
 * type, appending a numeric suffix when a file already exists.
 */
export async function findAvailableFilename(
  baseDirUri: string,
  blockType: BlockType,
  ide: IDE,
): Promise<string> {
  const extension = blockType === "rules" ? RULE_FILE_EXTENSION : "yaml";
  const baseName = `new-${BLOCK_FILE_BASE_NAMES[blockType]}`;

  let counter = 0;
  let fileUri: string;
  do {
    const suffix = counter === 0 ? "" : `-${counter}`;
    fileUri = joinPathsToUri(baseDirUri, `${baseName}${suffix}.${extension}`);
    counter++;
  } while (await ide.fileExists(fileUri));

  return fileUri;
}

export async function createNewWorkspaceBlockFile(
  ide: IDE,
  blockType: BlockType,
): Promise<void> {
  const workspaceDirs = await ide.getWorkspaceDirs();
  if (workspaceDirs.length === 0) {
    throw new Error(
      "No workspace directories found. Make sure you've opened a folder in your IDE.",
    );
  }

  const baseDirUri = joinPathsToUri(workspaceDirs[0], `.continue/${blockType}`);

  const fileUri = await findAvailableFilename(baseDirUri, blockType, ide);

  await ide.writeFile(fileUri, getFileContent(blockType));
  await ide.openFile(fileUri);
